from AlgorithmImports import *
import math


class IndependentDailyStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self._symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self._symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self._spy = self._symbols["SPY"]
        self._aapl = self._symbols["AAPL"]

        # 201 closes are needed to evaluate both today's and yesterday's 200-day SMA.
        self._spy_closes = RollingWindow[float](201)
        self._aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self._previous_aapl_close = None
        self._aapl_red_streak = 0

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

    def OnData(self, data: Slice):
        # Keep market-state quantities updating whenever their own bars are present.
        if data.Bars.ContainsKey(self._spy):
            self._spy_closes.Add(float(data.Bars[self._spy].Close))

        if data.Bars.ContainsKey(self._aapl):
            aapl_bar = data.Bars[self._aapl]
            aapl_close = float(aapl_bar.Close)

            self._aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self._previous_aapl_close is None:
                self._aapl_red_streak = 0
            elif aapl_close < self._previous_aapl_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

            self._previous_aapl_close = aapl_close

        # If any subscribed ticker is missing, do not evaluate any rules.
        for symbol in self._symbols.values():
            if not data.Bars.ContainsKey(symbol):
                return

        # Do not trade until every required indicator/window is fully formed.
        if not self._spy_closes.IsReady or not self._aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self._spy].Close)
        aapl_close = float(data.Bars[self._aapl].Close)

        spy_sma_200_today = sum(self._spy_closes[i] for i in range(200)) / 200.0
        spy_sma_200_yesterday = sum(self._spy_closes[i] for i in range(1, 201)) / 200.0
        spy_sma_50_today = sum(self._spy_closes[i] for i in range(50)) / 50.0
        spy_sma_50_yesterday = sum(self._spy_closes[i] for i in range(1, 51)) / 50.0

        spy_close_yesterday = self._spy_closes[1]

        # Sells are evaluated before buys.
        if self._strategy_a_lot > 0:
            crosses_below_50 = (
                spy_close_yesterday >= spy_sma_50_yesterday
                and spy_close < spy_sma_50_today
            )
            if crosses_below_50:
                self.MarketOrder(self._spy, -self._strategy_a_lot, "Strategy A sell")
                self._strategy_a_lot = 0

        if self._strategy_b_lot > 0 and self._aapl_rsi.Current.Value > 60:
            self.MarketOrder(self._aapl, -self._strategy_b_lot, "Strategy B sell")
            self._strategy_b_lot = 0

        if self._strategy_a_lot == 0:
            crosses_above_200 = (
                spy_close_yesterday <= spy_sma_200_yesterday
                and spy_close > spy_sma_200_today
            )
            if crosses_above_200:
                quantity = int(math.floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
                ))
                if quantity > 0:
                    self.MarketOrder(self._spy, quantity, "Strategy A buy")
                    self._strategy_a_lot = quantity

        if self._strategy_b_lot == 0 and self._aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                quantity = int(math.floor(20_000 / aapl_close))
                if quantity > 0:
                    self.MarketOrder(self._aapl, quantity, "Strategy B buy")
                    self._strategy_b_lot = quantity
