class IndependentDailyStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=201)
        self.aapl_closes = deque(maxlen=4)
        self.aapl_red_streak = 0

        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        if data.Bars is None:
            return

        bars = {}
        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        if self.spy in bars:
            self.spy_closes.append(float(bars[self.spy].Close))

        if self.aapl in bars:
            close = float(bars[self.aapl].Close)
            if len(self.aapl_closes) > 0:
                if close < self.aapl_closes[-1]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.append(close)

        if len(bars) != len(self.symbols):
            return

        if not self._rules_ready():
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        yesterday_spy_close = self.spy_closes[-2]
        sma_200_today = sum(list(self.spy_closes)[-200:]) / 200
        sma_200_yesterday = sum(list(self.spy_closes)[:200]) / 200
        sma_50_today = sum(list(self.spy_closes)[-50:]) / 50
        sma_50_yesterday = sum(list(self.spy_closes)[-51:-1]) / 50

        # Sells are evaluated before buys.
        if (
            self.strategy_a_lot > 0
            and yesterday_spy_close >= sma_50_yesterday
            and spy_close < sma_50_today
        ):
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and float(self.aapl_rsi.Current.Value) > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if (
            self.strategy_a_lot == 0
            and yesterday_spy_close <= sma_200_yesterday
            and spy_close > sma_200_today
        ):
            shares = floor(
                0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                shares = floor(20_000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_lot = shares

    def _rules_ready(self):
        return (
            len(self.spy_closes) == 201
            and len(self.aapl_closes) == 4
            and self.aapl_rsi.IsReady
        )
