from AlgorithmImports import *
import math


class IndependentDailyStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None

        self.spy_bar_count = 0
        self.aapl_bar_count = 0
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending_order = None
        self.strategy_b_pending_order = None
        self.order_actions = {}

    def OnData(self, data):
        has_spy = data.Bars.ContainsKey(self.spy)
        has_aapl = data.Bars.ContainsKey(self.aapl)

        if has_spy:
            spy_bar = data.Bars[self.spy]
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_bar_count += 1

        if has_aapl:
            aapl_bar = data.Bars[self.aapl]
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.aapl_bar_count += 1

            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close

        full_day = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)

        ready = (
            self.spy_bar_count >= 201 and
            self.aapl_bar_count >= 4 and
            self.spy_sma_200.IsReady and
            self.spy_sma_50.IsReady and
            self.aapl_rsi_14.IsReady and
            self.previous_spy_close is not None and
            self.previous_spy_sma_200 is not None and
            self.previous_spy_sma_50 is not None
        )

        if full_day and ready:
            spy_close = data.Bars[self.spy].Close
            aapl_close = data.Bars[self.aapl].Close

            # Sells are evaluated before buys.
            if self.strategy_a_lot > 0 and self.strategy_a_pending_order is None:
                if (self.previous_spy_close >= self.previous_spy_sma_50 and
                        spy_close < self.spy_sma_50.Current.Value):
                    self._submit_strategy_order("A", -self.strategy_a_lot, "Strategy A Sell")

            if self.strategy_b_lot > 0 and self.strategy_b_pending_order is None:
                if self.aapl_rsi_14.Current.Value > 60:
                    self._submit_strategy_order("B", -self.strategy_b_lot, "Strategy B Sell")

            if self.strategy_a_lot == 0 and self.strategy_a_pending_order is None:
                if (self.previous_spy_close <= self.previous_spy_sma_200 and
                        spy_close > self.spy_sma_200.Current.Value):
                    quantity = int(math.floor(
                        0.40 * self.Portfolio.TotalPortfolioValue / spy_close
                    ))
                    if quantity > 0:
                        self._submit_strategy_order("A", quantity, "Strategy A Buy")

            if self.strategy_b_lot == 0 and self.strategy_b_pending_order is None:
                if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                    quantity = int(math.floor(20_000 / aapl_close))
                    if quantity > 0:
                        self._submit_strategy_order("B", quantity, "Strategy B Buy")

        if has_spy:
            self.previous_spy_close = data.Bars[self.spy].Close
            self.previous_spy_sma_200 = (
                self.spy_sma_200.Current.Value if self.spy_sma_200.IsReady else None
            )
            self.previous_spy_sma_50 = (
                self.spy_sma_50.Current.Value if self.spy_sma_50.IsReady else None
            )

    def _submit_strategy_order(self, strategy, quantity, tag):
        symbol = self.spy if strategy == "A" else self.aapl
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket.OrderId > 0:
            self.order_actions[ticket.OrderId] = (strategy, quantity > 0)

            if strategy == "A":
                self.strategy_a_pending_order = ticket.OrderId
            else:
                self.strategy_b_pending_order = ticket.OrderId

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId not in self.order_actions:
            return

        strategy, is_buy = self.order_actions[orderEvent.OrderId]

        if orderEvent.FillQuantity != 0:
            filled_shares = abs(orderEvent.FillQuantity)

            if strategy == "A":
                if is_buy:
                    self.strategy_a_lot += filled_shares
                else:
                    self.strategy_a_lot = max(0, self.strategy_a_lot - filled_shares)
            else:
                if is_buy:
                    self.strategy_b_lot += filled_shares
                else:
                    self.strategy_b_lot = max(0, self.strategy_b_lot - filled_shares)

        if orderEvent.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if strategy == "A":
                self.strategy_a_pending_order = None
            else:
                self.strategy_b_pending_order = None

            del self.order_actions[orderEvent.OrderId]
