import math


class PrivateLotStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma_200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_closes = RollingWindow[float](2)
        self.spy_sma_200_values = RollingWindow[float](2)
        self.spy_sma_50_values = RollingWindow[float](2)

        self.last_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        # Continuously maintain market-state quantities for bars that are present.
        if spy_bar is not None:
            self.spy_closes.Add(float(spy_bar.Close))

            if self.spy_sma_200.IsReady:
                self.spy_sma_200_values.Add(float(self.spy_sma_200.Current.Value))

            if self.spy_sma_50.IsReady:
                self.spy_sma_50_values.Add(float(self.spy_sma_50.Current.Value))

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.last_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.last_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.last_aapl_close = aapl_close

        # A missing bar for any subscribed ticker skips all rule evaluation.
        if any(
            not data.Bars.ContainsKey(symbol) or data.Bars[symbol] is None
            for symbol in self.symbols
        ):
            return

        if self.IsWarmingUp:
            return

        spy_ready = (
            self.spy_closes.Count == 2
            and self.spy_sma_200_values.Count == 2
            and self.spy_sma_50_values.Count == 2
        )
        aapl_ready = self.aapl_rsi_14.IsReady and self.last_aapl_close is not None

        # Sell rules are evaluated before buy rules.
        if self.strategy_a_lot > 0 and spy_ready:
            crossed_below_50 = (
                self.spy_closes[1] >= self.spy_sma_50_values[1]
                and self.spy_closes[0] < self.spy_sma_50_values[0]
            )

            if crossed_below_50:
                self.MarketOrder(
                    self.spy,
                    -self.strategy_a_lot,
                    tag="Strategy A: sell entire private SPY lot",
                )
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and aapl_ready:
            if float(self.aapl_rsi_14.Current.Value) > 60:
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_lot,
                    tag="Strategy B: sell entire private AAPL lot",
                )
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_ready:
            crossed_above_200 = (
                self.spy_closes[1] <= self.spy_sma_200_values[1]
                and self.spy_closes[0] > self.spy_sma_200_values[0]
            )

            if crossed_above_200:
                shares = int(
                    math.floor(
                        0.40
                        * float(self.Portfolio.TotalPortfolioValue)
                        / float(spy_bar.Close)
                    )
                )

                if shares > 0:
                    self.MarketOrder(
                        self.spy,
                        shares,
                        tag="Strategy A: invest 40% of portfolio in SPY",
                    )
                    self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and aapl_ready:
            if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                shares = int(math.floor(20_000 / float(aapl_bar.Close)))

                if shares > 0:
                    self.MarketOrder(
                        self.aapl,
                        shares,
                        tag="Strategy B: buy $20,000 of AAPL",
                    )
                    self.strategy_b_lot = shares
